ALTER TABLE "public_top_threes" ADD CONSTRAINT "public_top_threes_games_shape_check" CHECK (jsonb_typeof("public_top_threes"."games") = 'array' and jsonb_array_length("public_top_threes"."games") = 3 and not jsonb_path_exists("public_top_threes"."games", '$[*] ? (@.type() != "object" || !exists(@.name) || @.name.type() != "string" || (exists(@.description) && @.description.type() != "string") || (exists(@.imageUrl) && @.imageUrl.type() != "string") || (exists(@.imageStorageKey) && @.imageStorageKey.type() != "string") || (exists(@.imageAlt) && @.imageAlt.type() != "string"))') and not jsonb_path_exists("public_top_threes"."games", '$[*].keyvalue() ? (@.key != "name" && @.key != "description" && @.key != "imageUrl" && @.key != "imageStorageKey" && @.key != "imageAlt")') and not jsonb_path_exists("public_top_threes"."games", '$[*] ? (!(@.name like_regex "^\\s*.{0,159}\\S\\s*$" flag "s") || (exists(@.description) && !(@.description like_regex "^\\s*.*\\S\\s*$" flag "s")) || ((exists(@.imageUrl) || exists(@.imageStorageKey) || exists(@.imageAlt)) && !(exists(@.imageUrl) && exists(@.imageStorageKey) && exists(@.imageAlt))))'));